const match = content.match(/\`\`\`braincode\n([\s\S]*?)\n\`\`\`/);
if (match) {
  const code = match[1];
  console.log('BrainCode extracted, length:', code.length);
  console.log('First 500 chars:');
  console.log(code.substring(0, 500));
  console.log('...');
  console.log('Last 200 chars:');
  console.log(code.substring(code.length - 200));
}
" 2>&1

